#if UNITY_EDITOR
using System;using System.IO;using System.Reflection;using UnityEngine;using UnityEditor;
namespace FashionFit.Editor {
 public static class ResponseOptimizationVerification {
  [Serializable]sealed class Result{public string status="passed",scope="Conservative picking broadphase versus pre-optimization exhaustive triangle search; actual fitted garment plus transformed/synthetic cases";public int checks,queries;public double referenceMs,optimizedMs;}
  static bool Reference(Vector3[] vertices,int[] faces,Matrix4x4 matrix,Vector3 world,float reach,out Vector3 point,out int vertex){point=world;vertex=-1;Vector3 local=matrix.inverse.MultiplyPoint3x4(world);float best=reach*reach;for(int i=0;i<faces.Length;i+=3){int a=faces[i],b=faces[i+1],c=faces[i+2];Vector3 q=GarmentPicking.Triangle(local,vertices[a],vertices[b],vertices[c]),w=matrix.MultiplyPoint3x4(q);float d=(w-world).sqrMagnitude;if(d<best){best=d;point=w;float da=(q-vertices[a]).sqrMagnitude,db=(q-vertices[b]).sqrMagnitude,dc=(q-vertices[c]).sqrMagnitude;vertex=da<db?(da<dc?a:c):(db<dc?b:c);}}return vertex>=0;}
  public static void RunBatch(){string folder=Path.GetFullPath("Verification/ResponseOptimization");Directory.CreateDirectory(folder);var r=new Result();GameObject root=null;try{root=new GameObject("Response picking proof");var app=root.AddComponent<FashionFitApp>();typeof(FashionFitApp).GetMethod("Start",BindingFlags.NonPublic|BindingFlags.Instance).Invoke(app,null);if(!app.Ready)throw new Exception(app.FatalError);var mesh=app.PoseStudio.Wearables[0].Surface.MeshAt(0);var v=mesh.vertices;var faces=mesh.triangles;var random=new System.Random(20261102);var matrices=new[]{Matrix4x4.identity,Matrix4x4.TRS(new Vector3(.5f,.1f,-.6f),Quaternion.Euler(12,37,-8),new Vector3(.8f,1.2f,1.1f)),Matrix4x4.TRS(Vector3.zero,Quaternion.Euler(0,91,0),new Vector3(-1.1f,.7f,1.3f))};
   foreach(var matrix in matrices)for(int i=0;i<220;i++){Vector3 local=v[random.Next(v.Length)]+new Vector3((float)random.NextDouble()-.5f,(float)random.NextDouble()-.5f,(float)random.NextDouble()-.5f)*.32f;Vector3 p=matrix.MultiplyPoint3x4(local);float reach=i%11==0?0:i%3==0?.025f:.11f;long t=System.Diagnostics.Stopwatch.GetTimestamp();bool a=Reference(v,faces,matrix,p,reach,out Vector3 pa,out int va);long middle=System.Diagnostics.Stopwatch.GetTimestamp();bool b=GarmentPicking.Mesh(v,faces,matrix,p,reach,out Vector3 pb,out int vb);long end=System.Diagnostics.Stopwatch.GetTimestamp();r.referenceMs+=(middle-t)*1000.0/System.Diagnostics.Stopwatch.Frequency;r.optimizedMs+=(end-middle)*1000.0/System.Diagnostics.Stopwatch.Frequency;r.queries++;r.checks++;if(a!=b||va!=vb||Vector3.Distance(pa,pb)>.000001f)throw new Exception("Picking mismatch "+r.queries);}
   UnityEngine.Object.DestroyImmediate(root);root=null;File.WriteAllText(folder+"/picking.json",JsonUtility.ToJson(r,true));EditorApplication.Exit(0);
  }catch(Exception e){r.status="failed";File.WriteAllText(folder+"/picking.json",JsonUtility.ToJson(r,true));File.WriteAllText(folder+"/failure.txt",e.ToString());if(root)UnityEngine.Object.DestroyImmediate(root);Debug.LogException(e);EditorApplication.Exit(1);}}
 }
}
#endif
